import {challenge as C} from './shared.js';
export default [
C(6,2,'把图像切成有顺序的 patch',{
 goal:'将二维灰度图切成不重叠的展平小块。',signature:'patchify(image, size)',contract:'image 是非空矩形数字列表，高宽均能被正整数 size 整除。按从上到下、从左到右的 patch 顺序输出，每个 patch 内也按行展开。',context:'视觉 token 并不是图片文件名。图像先被划分为空间位置，再经映射变成向量。顺序错误可能不影响数组形状，却破坏位置关系。这个任务先实现 patch 接口，不涉及训练视觉塔。',steps:['外层以 size 为步长遍历 patch 左上角行列。','内层读取 size×size 个像素并按行展平。','检查输出数量等于 (H/size)*(W/size)，每项长度为 size²。'],worked:['4×4 图像，size=2，共四个 patch。','第一个 patch 取行 0、1 和列 0、1。','第二个 patch 向右移动两列，不是从扁平数组随便取下一段。'],mistake:'整张图先展平再每 size² 项切片，通常不会得到正确二维区域。',transfer:'彩色图还需定义通道顺序，位置编码需与 patch 顺序一致；形状检查无法代替空间内容检查。',cases:[['patchify([[1,2,3,4],[5,6,7,8]],2)','[[1,2,5,6],[3,4,7,8]]','空间小块'],['patchify([[1,2],[3,4]],1)','[[1],[2],[3],[4]]','单像素 patch'],['patchify([[1,2],[3,4]],2)','[[1,2,3,4]]','整张一个 patch']],solution:'def patchify(image,size):\n    return [[image[r+i][c+j] for i in range(size) for j in range(size)] for r in range(0,len(image),size) for c in range(0,len(image[0]),size)]\n',quiz:['8×8 图像，patch 边长为 2，有几个位置？',['4','16','32'],1,'高宽各 4 块，总数 4×4=16。']
}),
C(6,4,'计算不受向量长度误导的相似度',{
 goal:'实现余弦相似度，比较表示方向。',signature:'cosine_similarity(a, b)',contract:'a、b 为同维非空有限向量。返回 dot(a,b)/(norm(a)*norm(b))；任何一个为零向量时约定返回 0。',context:'CLIP 类图文检索常在归一化表示上比较相似度。未经归一化的点积会受向量长度影响，数值很大的向量可能仅凭模长赢得匹配。本题单独实现方向比较，帮助理解“对齐”不是直接比原始像素和文本编号。',steps:['计算点积以及两向量的平方和。','零范数按题目约定返回 0，避免除零。','用范数乘积归一化；同方向结果 1，反方向 -1。'],worked:['a=[1,0]，b=[3,0]，点积 3。','范数乘积 1×3=3，所以余弦为 1。','把 b 放大 10 倍，结果仍为 1。'],mistake:'只除以一个向量的范数不能消除两侧尺度影响。',transfer:'相似度高低还要结合负样本和任务协议；高分并不能直接证明模型理解了所有语义。',cases:[['cosine_similarity([1,0],[3,0])','1','同方向'],['cosine_similarity([1,0],[-2,0])','-1','相反方向'],['cosine_similarity([1,0],[0,2])','0','正交'],['cosine_similarity([0,0],[1,2])','0','零向量约定']],solution:'import math\ndef cosine_similarity(a,b):\n    norm=math.sqrt(sum(x*x for x in a)*sum(x*x for x in b))\n    return sum(x*y for x,y in zip(a,b))/norm if norm else 0.0\n',quiz:['把非零向量乘以正数 100，它与另一个向量的余弦怎样变化？',['放大 100 倍','不变','变为零'],1,'分子与分母同比例变化。']
}),
C(6,6,'单独验收 codec 重建误差',{
 goal:'分别统计每张图像和总体的重建 MSE。',signature:'reconstruction_report(originals, decoded)',contract:'输入为等长非空图像列表；每张图用非空的一维像素列表表示，对应长度相同，不同图可有不同像素数。返回 {"per_image":每图MSE列表,"pixel_mse":按全部像素平均的MSE}。',context:'如果 codec 已经丢失关键信息，动态模型再强也无法从编码中恢复未保留的细节。先验收编码解码重建，可以把压缩问题与未来预测问题分开。同时要明确按图平均和按像素平均是不同协议。',steps:['每张图先求平方误差和，并记录像素数量。','每图误差除以该图像素数得到 per_image。','总体用全部误差和除以全部像素数，而不是简单平均 per_image。'],worked:['第一张只有一个像素，误差平方为 4。','第二张三个像素误差都为 0。','每图 MSE=[4,0]，总体 pixel_mse=4/4=1。'],mistake:'不同分辨率直接平均每图 MSE，会给小图每个像素更高权重。',transfer:'MSE 只描述像素误差；纹理、语义与动作相关信息仍需其他检查，本题不将低 MSE 等同于优秀表示。',cases:[['reconstruction_report([[2],[0,0,0]],[[0],[0,0,0]])','{"per_image":[4,0],"pixel_mse":1}','按像素加权'],['reconstruction_report([[1,2]],[[1,2]])','{"per_image":[0],"pixel_mse":0}','完美重建'],['reconstruction_report([[1,-1]],[[0,0]])','{"per_image":[1],"pixel_mse":1}','正负误差都计入']],solution:'def reconstruction_report(originals,decoded):\n    sums=[sum((x-y)**2 for x,y in zip(a,b)) for a,b in zip(originals,decoded)]\n    return {"per_image":[s/len(a) for s,a in zip(sums,originals)],"pixel_mse":sum(sums)/sum(len(a) for a in originals)}\n',quiz:['一张 1 像素图 MSE=4，一张 3 像素图 MSE=0，总体像素 MSE 是？',['2','1','4'],1,'按像素总误差 4 除以总像素 4。']
}),
C(6,7,'周项目：搭建图文向量检索评测器',{
 goal:'根据归一化相似度选文本，并统计检索命中率。',signature:'retrieval_report(images, texts, targets)',contract:'两组非零向量维度一致，文本列表非空，targets 为每个图像对应的正确文本下标。返回 {"indices":预测下标列表,"accuracy":命中比例}；相似度并列选最小下标，图像列表非空。',context:'视觉塔提供表示，检索器根据表示匹配候选，评测器判断命中。把三者分开后，能看出改进来自编码器、候选集合还是评分规则。本题给定已计算的向量，不伪装成训练了 CLIP。',steps:['对每个图像向量计算与全部文本向量的余弦。','选最高分下标，并保证并列时结果稳定。','对照 targets 统计准确率；targets 只能评分，不能参与候选选择。'],worked:['图像 [1,0]，文本 [[0,1],[2,0]]。','余弦分别为 0 和 1，所以预测下标 1。','若正确目标为 1，则该样本命中；若目标为 0，不能为了命中而改变预测。'],mistake:'把 targets 作为查表索引直接返回，会绕过模型而得到虚假满分。',transfer:'真实检索还应报告候选规模、重复项、Recall@K 等协议；本题先完成最小 top-1 链路。',cases:[['retrieval_report([[1,0],[0,1]],[[0,2],[3,0]],[1,0])','{"indices":[1,0],"accuracy":1}','两类匹配'],['retrieval_report([[1,0]],[[1,0],[2,0]],[1])','{"indices":[0],"accuracy":0}','并列取最早'],['retrieval_report([[-1,0]],[[1,0],[-1,0]],[1])','{"indices":[1],"accuracy":1}','方向而非绝对值']],solution:'import math\ndef retrieval_report(images,texts,targets):\n    def cos(a,b): return sum(x*y for x,y in zip(a,b))/math.sqrt(sum(x*x for x in a)*sum(y*y for y in b))\n    indices=[max(range(len(texts)),key=lambda i:cos(a,texts[i])) for a in images]\n    return {"indices":indices,"accuracy":sum(a==b for a,b in zip(indices,targets))/len(targets)}\n',quiz:['改变正确标签但保持输入向量不变，预测下标应怎样？',['保持不变','变成新标签','全部归零'],0,'评测标签不能参与推理。']
})];
